const me=()=>Number($('#person').value),manager=()=>me()<2,num=n=>Number(n).toLocaleString('fa-IR'),pct=n=>num(Math.round(n))+'٪',dateOnly=s=>s?String(s).slice(0,10):'',iso=d=>d.toISOString().slice(0,10),parse=s=>new Date(dateOnly(s)+'T12:00:00Z'),shift=(s,n)=>{let d=parse(s);d.setUTCDate(d.getUTCDate()+n);return iso(d)},late=t=>t.status!=='انجام‌شده'&&t.due&&t.due<day(0),progress=t=>t.status==='انجام‌شده'?100:Math.min(99,Math.max(0,Number(t.progress)||0)),canEdit=t=>manager()||t.owner===me();
