let toastTimer;function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').style.display='block';toastTimer=setTimeout(()=>$('#toast').style.display='none',2800)}
function statusClass(s){return s==='انجام‌شده'||s==='تحویل‌شده'?'done':s==='در حال انجام'||s==='در حال اجرا'?'progress':s==='متوقف‌شده'?'stopped':'new'}
