function taskTable(list,compact=false){if(!list.length)return empty();return `<div class="table-wrap"><table><thead><tr><th style="width:35px"></th><th>عنوان کار</th><th>مسئول</th><th>مهلت انجام</th><th>وضعیت</th>${compact?'':'<th>اولویت</th><th>پیشرفت</th><th>تاریخ تعریف</th>'}</tr></thead><tbody>${list.map(t=>`<tr><td><button class="check ${t.status==='انجام‌شده'?'checked':''}" data-complete="${t.id}" aria-label="${t.status==='انجام‌شده'?'بازگشایی':'اتمام'} ${esc(t.title)}" ${canEdit(t)?'':'disabled'}>${t.status==='انجام‌شده'?'✓':''}</button></td><td><button class="task-title" data-task="${t.id}">${esc(t.title)}${!compact&&t.reason?`<small>${esc(t.reason)}</small>`:''}</button></td><td>${person(t.owner)}</td><td class="${late(t)?'late':''}">${fmt(t.due)}${late(t)?'<br><small>عقب‌افتاده</small>':''}</td><td>${badge(t)}</td>${compact?'':`<td><span class="pill ${t.priority==='فوری'?'urgent':t.priority==='مهم'?'important':'normal'}">${esc(t.priority)}</span></td><td>${bar(progress(t))}</td><td class="muted">${fmt(t.created)}</td>`}</tr>`).join('')}</tbody></table></div>`}
