function navigate(v){view=v;query='';statusFilter='';ownerFilter='';render()}
function render(){if(view==='reports'&&!manager())view='dashboard';$('#title').textContent=names[view];$('#crumb').textContent=names[view];$('#subtitle').textContent=view==='reports'?'گزارش قابل دریافت برای مدیر پروژه و سرپرست کارگاه':view==='calendar'?'موعد کارها و تحویل‌های پروژه در تقویم شمسی':view==='timeline'?'بازه اجرا و تحویل‌های برنامه‌ریزی‌شده در یک نگاه':'شرکت سمندیس · پروژه دارایی';$('#today').textContent=fmt(now());$('#activeCount').textContent=num(tasks.filter(t=>t.status!=='انجام‌شده').length);$('#myAvatar').textContent=people[me()][0];$('#reportsNav').hidden=!manager();$('#reportsNav').style.display=manager()?'flex':'none';$('#addDelivery').hidden=!manager();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));const m=metrics(tasks);$('#stats').innerHTML=`<div class="stats">${[['کل کارهای پروژه',num(m.total),'تمام کارهای ثبت‌شده','☷'],['تکمیل کارها',m.completion===null?'—':pct(m.completion),num(m.done)+' کار انجام‌شده','✓'],['در حال انجام',num(tasks.filter(t=>t.status==='در حال انجام').length),'فعالیت‌های در جریان','↗'],['نیازمند پیگیری',num(m.late),'کارهای عبورکرده از مهلت','◷']].map(a=>`<div class="stat"><span class="stat-title">${a[0]}</span><span class="stat-icon">${a[3]}</span><strong class="stat-value">${a[1]}</strong><span class="stat-note">${a[2]}</span></div>`).join('')}</div>`;({dashboard:renderDashboard,active:renderTasks,mine:renderTasks,done:renderTasks,calendar:renderCalendar,timeline:renderTimeline,feed:renderFeed,reports:renderReports}[view])()}
function renderDashboard(){let m=metrics(tasks),states=['تعریف‌شده','در حال انجام','متوقف‌شده','انجام‌شده'],colors=['#e3e6ee','#9db8d7','#ead79b','#a6c4af'],sum=0,stops=states.map((s,i)=>{let count=tasks.filter(t=>t.status===s).length,p=tasks.length?count/tasks.length*100:0;let str=`${colors[i]} ${sum}% ${sum+p}%`;sum+=p;return str});let upcoming=deliveries.filter(d=>d.status!=='تحویل‌شده').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);$('#workspace').innerHTML=`<div class="dashboard-grid">${panel('کارهای در جریان',taskTable(tasks.filter(t=>t.status!=='انجام‌شده').slice(0,5),true),'<button class="text-btn" data-go="active">همه کارها ←</button>')}${panel('وضعیت کارها',`<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${tasks.length?stops.join(','):'#edf0f4 0% 100%'})"><div><b>${m.completion===null?'—':pct(m.completion)}</b><small>تکمیل‌شده</small></div></div><div class="legend">${states.map((s,i)=>`<div><i style="background:${colors[i]}"></i>${s}<b>${num(tasks.filter(t=>t.status===s).length)}</b></div>`).join('')}</div></div>`)}${panel('آخرین فعالیت‌های تیم',activityRows(logs().slice(0,4)),'<button class="text-btn" data-go="feed">همه فعالیت‌ها ←</button>')}${panel('تحویل‌های پیش رو',deliveryRows(upcoming),'<button class="text-btn" data-go="timeline">تایملاین ←</button>')}</div>`}
