const persianParts=s=>Object.fromEntries(new Intl.DateTimeFormat('en-US-u-ca-persian',{timeZone:'UTC',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(parse(s)).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
