function renderTimeline(){let rows=[...deliveries.map(d=>({...d,type:'delivery'})),...tasks.filter(t=>t.due).map(t=>({...t,start:t.start||dateOnly(t.created),type:'task'}))];let allDates=rows.flatMap(t=>[t.start,t.due]).filter(Boolean).sort(),start=shift(allDates[0]||day(0),-2),end=shift(allDates.at(-1)||day(20),3),span=Math.max(1,(parse(end)-parse(start))/86400000),position=s=>(parse(s)-parse(start))/86400000/span*100;let row=t=>{let a=position(t.start||t.due),b=position(t.due);return `<div class="time-row"><div class="time-label"><button class="task-title" data-${t.type}="${t.id}">${esc(t.title)}</button><small>${fmt(t.start)} تا ${fmt(t.due)}</small></div><div class="time-track">${position(day(0))>=0&&position(day(0))<=100?`<i class="today-line" style="right:${position(day(0))}%" title="امروز"></i>`:''}<button class="time-bar ${t.type==='delivery'?'delivery':''} ${statusClass(t.status)==='done'?'completed':''}" data-${t.type}="${t.id}" style="right:${Math.max(0,a)}%;width:${Math.max(1,b-a)}%" title="${esc(t.title)} · ${esc(t.status)}">${esc(t.status)}</button></div></div>`};$('#workspace').innerHTML=`<div class="panel"><div class="panel-header"><h2>برنامه اجرا و تحویل پروژه</h2><small>خط عمودی: امروز · زرد: تحویل · آبی: کار</small></div><div class="timeline-shell"><div class="timeline"><div class="time-header"><div class="time-label">بازه برنامه‌ریزی‌شده</div><div class="time-scale">${Array.from({length:8},(_,i)=>`<span>${fmt(shift(start,Math.round(span*i/7)))}</span>`).join('')}</div></div><div class="section-label">تحویل‌های پروژه</div>${rows.filter(t=>t.type==='delivery').map(row).join('')||empty('تحویلی ثبت نشده')}<div class="section-label">کارهای زمان‌بندی‌شده</div>${rows.filter(t=>t.type==='task').map(row).join('')||empty('کار دارای مهلت ثبت نشده')}</div></div></div>${tasks.some(t=>!t.due)?`<div class="formula">${num(tasks.filter(t=>!t.due).length)} کار بدون مهلت است و روی تایملاین نمایش داده نمی‌شود.</div>`:''}`}
function periodTasks(i){return tasks.filter(t=>(i===''||t.owner===Number(i))&&(!reportFrom||tehranDate(t.created)>=reportFrom)&&(!reportTo||tehranDate(t.created)<=reportTo))}function periodLogs(i){return logs().filter(r=>(i===''||r.person===Number(i))&&(!reportFrom||tehranDate(r.time)>=reportFrom)&&(!reportTo||tehranDate(r.time)<=reportTo))}
function renderReports(){if(!manager())return;const rows=people.map((p,i)=>({i,m:metrics(periodTasks(i)),logs:periodLogs(i).filter(r=>r.hours||!r.text.startsWith('کار «'))})).filter(r=>reportPerson===''||String(r.i)===reportPerson),list=periodTasks(reportPerson),m=metrics(list),worklogs=periodLogs(reportPerson),hours=worklogs.reduce((a,r)=>a+(Number(r.hours)||0),0);$('#workspace').innerHTML=`<div class="report-filter"><label>عضو تیم<select id="reportPerson"><option value="">همه اعضا</option>${people.map((p,i)=>`<option value="${i}" ${reportPerson===String(i)?'selected':''}>${p}</option>`).join('')}</select></label><label>از تاریخ<input type="date" id="reportFrom" value="${esc(reportFrom)}"></label><label>تا تاریخ<input type="date" id="reportTo" value="${esc(reportTo)}"></label><button id="clearReport" class="text-btn">حذف فیلتر</button><button id="exportReport" class="secondary">↓ دریافت گزارش CSV</button></div><div class="formula">مبنای بازه کارها: تاریخ تعریف؛ مبنای فعالیت‌ها و ساعت‌ها: تاریخ ثبت گزارش. همه تاریخ‌ها در خروجی شمسی هستند.<br>تکمیل = کارهای انجام‌شده ÷ کل کارها. میانگین پیشرفت = میانگین درصد اعلام‌شده کارها با وزن برابر. تحویل به‌موقع = کارهای تمام‌شده در مهلت ÷ کارهای تمام‌شده دارای مهلت و تاریخ اتمام. بدون داده، «—» نمایش داده می‌شود.<br>این شاخص‌ها پیشرفت کارها را نشان می‌دهند؛ سختی کار، کیفیت اجرا و علت تأخیر در آن‌ها وزن‌گذاری نشده است.</div><div class="report-summary">${[['نرخ تکمیل',m.completion===null?'—':pct(m.completion),num(m.done)+' از '+num(m.total)+' کار'],['میانگین پیشرفت',m.average===null?'—':pct(m.average),'بر اساس درصد اعلام‌شده'],['ساعات گزارش‌شده',num(hours),'ثبت‌شده توسط اعضا']].map(a=>`<div class="report-kpi"><span>${a[0]}</span><b>${a[1]}</b><span>${a[2]}</span></div>`).join('')}</div>${panel('کارکرد اعضای تیم',`<div class="table-wrap"><table><thead><tr><th>عضو</th><th>کل کارها</th><th>انجام‌شده</th><th>تکمیل</th><th>میانگین پیشرفت</th><th>تحویل به‌موقع</th><th>عقب‌افتاده</th><th>ساعت ثبت‌شده</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${person(r.i)}</td><td>${num(r.m.total)}</td><td>${num(r.m.done)}</td><td>${r.m.completion===null?'—':bar(r.m.completion)}</td><td>${r.m.average===null?'—':pct(r.m.average)}</td><td>${r.m.timely===null?'—':pct(r.m.timely)+` <small class="muted">(${num(r.m.onTime)}/${num(r.m.dated)})</small>`}</td><td>${num(r.m.late)}</td><td>${num(periodLogs(r.i).reduce((a,l)=>a+(Number(l.hours)||0),0))}</td><td><button class="table-action" data-report-person="${r.i}">جزئیات ←</button></td></tr>`).join('')}</tbody></table></div>`)}${reportPerson!==''?`<div class="person-detail report-grid">${panel('کارهای '+esc(people[Number(reportPerson)]),taskTable(list,true))}${panel('گزارش‌های ثبت‌شده این فرد',activityRows(worklogs))}</div>`:''}`;['reportPerson','reportFrom','reportTo'].forEach(id=>$('#'+id).onchange=e=>{if(id==='reportPerson')reportPerson=e.target.value;if(id==='reportFrom')reportFrom=e.target.value;if(id==='reportTo')reportTo=e.target.value;if(reportFrom&&reportTo&&reportFrom>reportTo){toast('بازه تاریخ معتبر نیست');if(id==='reportFrom')reportFrom='';else reportTo=''}renderReports()});$('#clearReport').onclick=()=>{reportPerson=reportFrom=reportTo='';renderReports()};$('#exportReport').onclick=exportReport}
function exportReport(){if(!manager())return;let rows=[['شرکت سمندیس - پروژه دارایی'],['بازه تعریف کارها',fmt(reportFrom),fmt(reportTo)],['عضو','کل کارها','انجام‌شده','تکمیل (%)','میانگین پیشرفت (%)','تحویل به‌موقع (%)','عقب‌افتاده','ساعات ثبت‌شده']];people.forEach((p,i)=>{if(reportPerson!==''&&Number(reportPerson)!==i)return;let m=metrics(periodTasks(i));rows.push([p,m.total,m.done,m.completion===null?'':Math.round(m.completion),m.average===null?'':Math.round(m.average),m.timely===null?'':Math.round(m.timely),m.late,periodLogs(i).reduce((a,r)=>a+(Number(r.hours)||0),0)])});rows.push([],['جزئیات کارها'],['عنوان','مسئول','وضعیت','پیشرفت (%)','تعریف','مهلت','اتمام']);periodTasks(reportPerson).forEach(t=>rows.push([t.title,people[t.owner],t.status,progress(t),fmt(t.created),fmt(t.due),fmt(t.completed)]));rows.push([],['گزارش فعالیت‌ها'],['نام','کار','گزارش','تاریخ','ساعت']);periodLogs(reportPerson).forEach(r=>rows.push([people[r.person],r.task,r.text,fmt(r.time),r.hours||0]));let cell=v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'},csv='\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n'),a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='samandis-daraei-report-'+day(0)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('گزارش دریافت شد')}
function logChange(t,text,hours=0){t.reports.push({person:me(),time:now(),text,hours})}
function complete(t){if(!canEdit(t))return;let done=t.status!=='انجام‌شده';t.status=done?'انجام‌شده':'تعریف‌شده';t.progress=done?100:0;t.completed=done?now():null;t.reason='';logChange(t,done?'کار را انجام‌شده کرد.':'کار را دوباره باز کرد.');save();toast(done?'کار به انجام‌شده‌ها منتقل شد':'کار بازگشایی شد')}
function detail(id){let t=tasks.find(t=>t.id===id);if(!t)return;selected=id;$('#detailBody').innerHTML=`<div class="dialog-head"><h2>${esc(t.title)}</h2><button class="close" data-detail-close>×</button></div>${badge(t)}<p class="detail-description">${esc(t.description)}</p><div class="detail-meta">${[['مسئول',people[t.owner]],['ثبت‌کننده',people[t.creator]],['تاریخ تعریف',fmt(t.created)],['مهلت انجام',fmt(t.due)],['شروع برنامه',fmt(t.start)],['تاریخ اتمام',fmt(t.completed)]].map(a=>`<div><span>${a[0]}</span><b>${esc(a[1])}</b></div>`).join('')}</div>${t.reason?`<p class="hint">دلیل توقف: ${esc(t.reason)}</p>`:''}<div class="detail-progress"><span class="muted">پیشرفت کار</span>${bar(progress(t))}</div>${canEdit(t)?`<div class="detail-actions">${['در حال انجام','متوقف‌شده','انجام‌شده','تعریف‌شده'].filter(s=>s!==t.status).map(s=>`<button class="${s==='انجام‌شده'?'finish':''}" data-status="${s}">${s==='تعریف‌شده'?'بازگشایی':s}</button>`).join('')}</div>${t.status!=='انجام‌شده'?`<form id="progressForm"><div class="detail-progress"><label>درصد پیشرفت<input name="progress" type="number" min="0" max="100" value="${progress(t)}" required></label><button class="secondary">ثبت پیشرفت</button></div></form>`:''}`:''}<h3 class="report-block-title">گزارش‌های این کار</h3>${t.reports.map(r=>`<div class="report-item"><b>${esc(people[r.person])}</b><span class="hours">${r.hours?num(r.hours)+' ساعت':''}</span><br>${esc(r.text)}<br><small>${fmt(r.time)}</small></div>`).join('')||'<p class="hint">هنوز گزارشی ثبت نشده.</p>'}<form id="reportForm"><label>گزارش فعالیت<textarea name="text" required rows="3" maxlength="3000" placeholder="چه کاری انجام دادید؟"></textarea></label><div class="fields"><label>زمان صرف‌شده (ساعت، اختیاری)<input type="number" name="hours" min="0" max="24" step="0.25" placeholder="مثلاً ۲"></label></div><button class="primary">ثبت گزارش برای همه</button></form>`;if(!$('#details').open)$('#details').showModal();$('[data-detail-close]').onclick=()=>$('#details').close();$('#detailBody').querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{if(!canEdit(t))return;let s=b.dataset.status;if(s==='انجام‌شده'){complete(t);detail(id);return}let reason='';if(s==='متوقف‌شده'){reason=prompt('دلیل توقف چیست؟');if(!reason?.trim())return}t.status=s;t.reason=reason;t.completed=null;if(s==='تعریف‌شده')t.progress=0;logChange(t,'وضعیت به «'+s+'» تغییر کرد.'+(reason?' دلیل: '+reason:''));save();detail(id)});if($('#progressForm'))$('#progressForm').onsubmit=e=>{e.preventDefault();if(!canEdit(t))return;let p=Number(new FormData(e.target).get('progress'));if(p===100){complete(t);detail(id);return}t.progress=p;if(p>0&&t.status==='تعریف‌شده')t.status='در حال انجام';logChange(t,'پیشرفت کار را '+pct(p)+' ثبت کرد.');save();detail(id);toast('پیشرفت ثبت شد')};$('#reportForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.text.trim())return;logChange(t,d.text.trim(),Number(d.hours)||0);save();detail(id);toast('گزارش ثبت شد')}}
function deliveryDetail(id){let d=deliveries.find(d=>d.id===id);if(!d)return;$('#detailBody').innerHTML=`<div class="dialog-head"><h2>${esc(d.title)}</h2><button class="close" data-detail-close>×</button></div>${badge(d)}<p class="detail-description">${esc(d.description)}</p><div class="detail-meta"><div><span>شروع بازه</span><b>${fmt(d.start)}</b></div><div><span>موعد تحویل</span><b>${fmt(d.due)}</b></div><div><span>مسئول هماهنگی</span><b>${esc(people[d.owner])}</b></div><div><span>نوع</span><b>تحویل پروژه${d.sample?' · نمونه':''}</b></div></div>${manager()?'<button id="editDelivery" class="primary">ویرایش موعد و وضعیت</button>':''}`;if(!$('#details').open)$('#details').showModal();$('[data-detail-close]').onclick=()=>$('#details').close();if($('#editDelivery'))$('#editDelivery').onclick=()=>{$('#details').close();openDelivery(d)}}
function openDelivery(d=null){if(!manager())return;editDelivery=d?.id||null;$('#deliveryForm').reset();$('#deliveryFormTitle').textContent=d?'ویرایش تحویل':'ثبت موعد تحویل';$('#deliveryOwner').value=d?.owner??me();if(d)for(const name of ['title','description','start','due','status'])$('#deliveryForm').elements[name].value=d[name]||'';$('#deliveryEditor').showModal()}
$('#taskOwner').innerHTML=$('#deliveryOwner').innerHTML=people.map((p,i)=>`<option value="${i}">${p}</option>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#person').onchange=()=>{$('#details').close();$('#editor').close();$('#deliveryEditor').close();render()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#add').onclick=()=>{$('#taskForm').reset();$('#taskOwner').value=me();$('#taskOwner').disabled=!manager();$('#editor').showModal()};$('#addDelivery').onclick=()=>openDelivery();$('#taskForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.title.trim())return;if(d.start&&d.due&&d.start>d.due)return toast('مهلت انجام باید بعد از شروع باشد');if(d.status==='متوقف‌شده'&&!d.reason.trim())return toast('دلیل توقف را بنویسید');let p=Number(d.progress);if(p===100)d.status='انجام‌شده';if(p>0&&d.status==='تعریف‌شده')d.status='در حال انجام';let t={...d,title:d.title.trim(),id:crypto.randomUUID(),owner:manager()?Number(d.owner):me(),creator:me(),created:now(),progress:d.status==='انجام‌شده'?100:p,completed:d.status==='انجام‌شده'?now():null,reports:[]};tasks.unshift(t);$('#editor').close();view=t.status==='انجام‌شده'?'done':'active';query=statusFilter=ownerFilter='';save();toast('کار جدید ثبت شد')};$('#deliveryForm').onsubmit=e=>{e.preventDefault();if(!manager())return;let d=Object.fromEntries(new FormData(e.target));if(!d.title.trim())return;if(d.start>d.due)return toast('موعد تحویل باید بعد از شروع باشد');d.owner=Number(d.owner);if(editDelivery){let old=deliveries.find(t=>t.id===editDelivery);Object.assign(old,d)}else deliveries.push({...d,id:crypto.randomUUID(),sample:false});$('#deliveryEditor').close();save();toast('تحویل ذخیره شد')};
$('#workspace').onclick=e=>{let b=e.target.closest('button,[data-delivery]');if(!b)return;if(b.dataset.go)return navigate(b.dataset.go);if(b.dataset.task)return detail(b.dataset.task);if(b.dataset.delivery)return deliveryDetail(b.dataset.delivery);if(b.dataset.complete){let t=tasks.find(t=>t.id===b.dataset.complete);if(t)complete(t);return}if(b.dataset.reportPerson!==undefined&&manager()){reportPerson=b.dataset.reportPerson;renderReports();return}if(b.dataset.month){let {start,end}=monthBounds(calendarAnchor);calendarAnchor=b.dataset.month==='prev'?shift(start,-1):b.dataset.month==='next'?shift(end,1):day(0);renderCalendar()}};$('#workspace').onkeydown=e=>{if(e.key==='Enter'){let row=e.target.closest('[data-delivery]');if(row)deliveryDetail(row.dataset.delivery)}};render();
